class RetryDispatcher:
    def __init__(self, max_attempts=3, base_delay=0.1, max_delay=1.0):
        # Validate constructor arguments
        if type(max_attempts) is not int or max_attempts <= 0:
            raise ValueError("max_attempts must be a positive integer")
        if isinstance(base_delay, bool) or not isinstance(base_delay, (int, float)) or base_delay <= 0:
            raise ValueError("base_delay must be a positive number")
        if isinstance(max_delay, bool) or not isinstance(max_delay, (int, float)) or max_delay <= 0:
            raise ValueError("max_delay must be a positive number")
        if max_delay < base_delay:
            raise ValueError("max_delay cannot be less than base_delay")
        self.max_attempts = max_attempts
        self.base_delay = float(base_delay)
        self.max_delay = float(max_delay)

    def calculate_backoff(self, attempt):
        # Validate attempt number
        if type(attempt) is not int or attempt <= 0:
            raise ValueError("attempt must be a positive integer")
        # Exponential backoff clamped to max_delay
        delay = self.base_delay * (2 ** (attempt - 1))
        return min(delay, self.max_delay)

    def execute(self, func, payload, dlq_sink):
        """Execute *func* with *payload* applying retry semantics.

        - Retries only ``RetryableError`` up to ``max_attempts``.
        - ``NonRetryableError`` (or any other unexpected exception) is sent immediately to the DLQ.
        - After exhausting retries, the last ``RetryableError`` is sent to the DLQ with the attempt count.
        - Returns the successful result of ``func``.
        """
        # Input validation
        if not callable(func):
            raise ValueError("func must be callable")
        # payload can be any value, but we reject ``None`` as it often signals missing data
        if payload is None:
            raise ValueError("payload must not be None")
        if not hasattr(dlq_sink, "send") or not callable(getattr(dlq_sink, "send")):
            raise ValueError("dlq_sink must have a callable 'send' method")

        attempts = 0
        last_err = None
        while attempts < self.max_attempts:
            attempts += 1
            try:
                return func(payload)
            except NonRetryableError as e:
                # Immediate DLQ routing for non‑retryable errors
                dlq_sink.send(payload, e, attempts)
                raise
            except RetryableError as e:
                last_err = e
                if attempts >= self.max_attempts:
                    # Exhausted retries – route to DLQ with metadata
                    dlq_sink.send(payload, e, attempts)
                    raise
                # Apply exponential backoff before next attempt
                delay = self.calculate_backoff(attempts)
                try:
                    import time
                    time.sleep(delay)
                except Exception:
                    # If sleeping fails, continue without delaying – do not swallow original error
                    pass
            except Exception as e:
                # Treat any other exception as non‑retryable
                dlq_sink.send(payload, e, attempts)
                raise
        # If loop exits without returning, raise the last captured error
        if last_err is not None:
            raise last_err
        raise RuntimeError("RetryDispatcher execution failed without captured exception")

