        if type(attempt) is not int or attempt <= 0:
            raise ValueError("attempt must be a positive integer")
        delay = self.base_delay * (2 ** (attempt - 1))
        return min(delay, self.max_delay)

    def execute(self, func, payload, dlq_sink):
        """Execute *func* with *payload* applying retry semantics.

        - *func* must be callable.
        - *dlq_sink* must provide a ``send(payload, error, attempts)`` method.
        - ``NonRetryableError`` triggers immediate DLQ routing.
        - ``RetryableError`` triggers retries with exponential backoff; on exhaustion it is routed to DLQ.
        """
        # Input validation
        if not callable(func):
            raise TypeError("func must be callable")
        if dlq_sink is None or not hasattr(dlq_sink, "send"):
            raise TypeError("dlq_sink must have a 'send' method")
        # payload can be any value, including None, but we guard against mutable default misuse elsewhere.

        attempts = 0
        last_err = None
        while attempts < self.max_attempts:
            attempts += 1
            try:
                return func(payload)
            except NonRetryableError as e:
                # Immediate dead‑letter routing, no further retries
                dlq_sink.send(payload, e, attempts)
                raise
            except RetryableError as e:
                last_err = e
                if attempts >= self.max_attempts:
                    # Exhausted retries – route to DLQ with metadata
                    dlq_sink.send(payload, e, attempts)
                    raise
                # Apply exponential backoff before next attempt
                delay = self.calculate_backoff(attempts)
                try:
                    import time
                    time.sleep(delay)
                except Exception:
                    # Sleep failures should not mask the original error
                    pass
                continue
            except Exception as e:
                # Any other exception is treated as non‑retryable
                dlq_sink.send(payload, e, attempts)
                raise
        # If loop exits without returning, raise the last captured error
        if last_err is not None:
            raise last_err
        raise RuntimeError("Unexpected execution flow in RetryDispatcher.execute")
